  "The translation appears here": "La traducción aparece aquí",
  "Every part is checked: numbers, names and codes kept exactly.": "Cada parte se comprueba: números, nombres y códigos se mantienen exactos.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Abre un PDF, un archivo Word, un libro o una página web. Léelo aquí y chatea con él: cada respuesta muestra la página de la que salió. Todo se queda en tu teléfono.",
  "Open a file": "Abrir un archivo",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "Leer y buscar ya funcionan. Para chatear con el archivo, instala un modelo en Motor.",
  "Your documents appear here": "Tus documentos aparecen aquí",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Abre un archivo: se guarda en este dispositivo con su chat y sus notas, para que puedas volver a él.",
  "Stop": "Detener",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Descríbelo en una frase: la IA de tu teléfono escribe un PowerPoint diseñado o un informe completo, desde la web o tu propio archivo. Edita cualquier diapositiva y guárdalo como PowerPoint, Word o PDF.",
  "Presentation": "Presentación",
  "Report": "Informe",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "p. ej., Una presentación de nuestra cafetería para oficinas de Nuevo Cairo: menú, catering, precios, por qué nosotros",
  "Research the web for facts and figures": "Buscar datos y cifras en la web",
  "Each slide names its sources, and a Sources slide lists every page": "Cada diapositiva cita sus fuentes y una diapositiva de Fuentes enumera cada página",
  "Base it on my file (Word, PDF, Excel, CSV…)": "Basarlo en mi archivo (Word, PDF, Excel, CSV…)",
  "Make the presentation": "Crear la presentación",
  "{n} slides": "{n} diapositivas",
  "Midnight": "Medianoche",
  "Short points": "Puntos breves",
  "Change": "Cambiar",
  "Your slides appear here": "Tus diapositivas aparecen aquí",
  "Each slide or section shows here as it is written.": "Cada diapositiva o sección aparece aquí a medida que se escribe.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Crea un CV en inglés o árabe, guarda una copia para cada empleo y exporta un PDF o Word limpio. La IA de tu teléfono ayuda con la redacción.",
  "New CV": "Nuevo CV",
  "Import my CV": "Importar mi CV",
  "No CVs yet": "Aún no hay CV",
  "Start a new one, or import the one you already have.": "Empieza uno nuevo o importa el que ya tienes.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Copia el enlace de un vídeo, pégalo aquí y elige la calidad: se guarda en la carpeta Películas de tu teléfono. Funciona con enlaces directos de vídeo, Google Drive, Dropbox, archive.org, Wikimedia Commons y páginas que muestran un vídeo simple.",
  "Find the video": "Buscar el vídeo",
  "The video's versions appear here": "Las versiones del vídeo aparecen aquí",
  "Paste a link and tap Find the video — then pick the quality to download.": "Pega un enlace y toca Buscar el vídeo; luego elige la calidad para descargar.",
  "No map on this device yet": "Aún no hay mapa en este dispositivo",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "Descarga el mapa del mundo para ver todos los países, o el de tu país para calles, lugares y búsqueda sin conexión.",
