  "Search a place and tap “Save” — saved places work with no signal.": "Busca un lugar y toca «Guardar»: los lugares guardados funcionan sin cobertura.",
  "Flight delayed or cancelled?": "¿Vuelo retrasado o cancelado?",
  "See what the airline owes you — up to €600 — and get the letter": "Mira lo que te debe la aerolínea —hasta 600 €— y consigue la carta",
