  "Download once on Wi-Fi — everything then works on a plane, in a tunnel, or with roaming switched off.": "Descarga una vez con wifi: después todo funciona en un avión, en un túnel o con la itinerancia desactivada.",
  "Find a country…": "Buscar un país…",
