  "Studio draws pictures with the phone's own chip — it works in the Android app.": "Estudio dibuja imágenes con el chip del propio teléfono: funciona en la app de Android.",
  "Steps": "Pasos",
  "Starting Python…": "Iniciando Python…",
  "Code that is tested before you get it": "Código probado antes de que lo recibas",
  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "El modelo escribe el programa y sus pruebas, el teléfono las ejecuta y cualquier error vuelve directamente al modelo para que lo arregle, hasta que pasan las pruebas. Sin conexión, en un entorno aislado.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "¿Qué debe hacer? p. ej., «Una función que divide la cuenta del restaurante entre amigos, con la propina»",
  "Web page": "Página web",
  "Build & test": "Crear y probar",
  "The program and its tests appear here": "El programa y sus pruebas aparecen aquí",
  "Each step, the code, a live preview for web pages, and whether the tests passed.": "Cada paso, el código, una vista previa en directo para páginas web y si las pruebas pasaron.",
