  "fits · {p}% of the window": "cabe · {p} % de la ventana",
  "A quarter of the window is held back for the answer — a prompt that exactly fills the context leaves no room to reply.": "Una cuarta parte de la ventana se reserva para la respuesta: un prompt que llena exactamente el contexto no deja sitio para responder.",
  "Port context to": "Llevar el contexto a",
