  "AI Compress": "Comprimir con IA",
  "Port": "Llevar",
  "= instant filler removal (offline).": "= eliminación instantánea de relleno (sin conexión).",
  "= the model rewrites it far shorter while keeping the meaning.": "= el modelo lo reescribe mucho más corto manteniendo el sentido.",
  "Result": "Resultado",
  "Paste a wordy prompt and hit": "Pega un prompt recargado y toca",
  "— it thinks about meaning, not just filler words.": "— piensa en el sentido, no solo en las palabras de relleno.",
  "Text to rewrite": "Texto para reescribir",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Pega un texto generado por IA o rígido: vuelve como si lo hubiera escrito una persona.",
  "Your writing sample": "Tu muestra de escritura",
  "(this is what makes it sound like you)": "(esto es lo que hace que suene como tú)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Pega unos párrafos que hayas escrito tú: un correo, un mensaje, lo que sea con tu voz natural.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Mantiene exactamente tu sentido y tus datos; solo cambia cómo se lee. La muestra es opcional, pero es lo que más se nota.",
  "Rewritten": "Reescrito",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Pega un texto rígido o con aire de IA, añade una muestra de tu escritura y vuelve con tu voz: mismo sentido, ritmo humano.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Chatea a través de Attune: lee toda la conversación y afina cada siguiente prompt.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "¿Qué quieres sacar de toda esta conversación? (opcional, pero mejora cada prompt)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Trae el chat de {t}: pega toda la conversación o solo su última respuesta:",
  "Paste here…": "Pega aquí…",
  "Read it & suggest my reply": "Leerlo y sugerir mi respuesta",
  "What do you want to ask? Type it however you like.": "¿Qué quieres preguntar? Escríbelo como quieras.",
  "Optimize my prompt": "Optimizar mi prompt",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "El ciclo: escribe la intención → obtén un prompt optimizado → envíalo → trae la respuesta → cada siguiente prompt es más preciso. En la app, el menú Compartir sustituye por completo a copiar y pegar.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Recetas de prompts listas: elige una, rellena los huecos y luego",
  "to tailor it.": "para adaptarla.",
