  "Ask it anything.": "Pregúntale lo que quieras.",
  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "Responde desde este dispositivo y puede revisar todo lo que le has preguntado antes, así que las preguntas sobre tu propio trabajo tienen respuestas reales, no suposiciones.",
