  "per company system, once": "por sistema de empresa, una vez",
  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro se compra en la versión de Attune de Google Play: un toque, pagas con tarjeta o con tu saldo de Vodafone / Orange / Etisalat, y se activa solo.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Cancela cuando quieras en Google Play → Suscripciones. El plan se renueva solo; no hay que enviar nada ni escribir a nadie.",
