  "Keep": "Guardar",
  "filing…": "ordenando…",
  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "Gratis: guarda y busca todo. Pro: ordena cada elemento solo (título, resumen, etiquetas), lee tus fotos y responde preguntas desde tu Mente.",
