  "from your past": "de tu pasado",
  "Nothing to read in that.": "No hay nada que leer ahí.",
  "That payment did not go through, so there is nothing to record.": "Ese pago no se completó, así que no hay nada que registrar.",
  "Sent to Yusr — pick the account and confirm": "Enviado a Yusr: elige la cuenta y confirma",
  "Money isn't bundled in this build.": "Dinero no está incluido en esta versión.",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "El documento de Yusr no está incluido. En el teléfono se carga desde los archivos de la app.",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "Tu libro de cuentas y cada regla del zakat están aquí, sin cambios y gratis para siempre. Attune añade memoria y explicaciones sencillas encima: nunca calcula el zakat y nunca mueve dinero por su cuenta.",
  "Share a payment": "Compartir un pago",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "Una confirmación de InstaPay, un SMS del banco, un recibo de la billetera o una foto de uno. Attune lee el importe y a quién fue, y abre tu propia ficha de movimiento ya rellenada. Tú eliges la cuenta.",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321",
  "Read it": "Leer",
  "Reading…": "Leyendo…",
  "From a photo": "Desde una foto",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "Tres formas, todas válidas: comparte el SMS, el mensaje de WhatsApp o la captura con Attune desde cualquier app (llega aquí solo) · pégalo arriba · o haz o elige una foto del recibo.",
  "read from: “": "leído de: “",
  "· account: you choose, in Yusr": "· cuenta: la eliges tú, en Yusr",
  "Talk to your money": "Habla con tu dinero",
  "not saved to memory": "no guardado en la memoria",
  "saved to memory": "guardado en la memoria",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "Respondido en este dispositivo con las cifras que calculó Yusr. Haz más preguntas: sigue el hilo. Para el zakat recibe los números de la propia app y tiene prohibido recalcularlos: explica, no dictamina.",
  "figures from Yusr's zakāt engine, not recalculated": "cifras del motor de zakat de Yusr, sin recalcular",
