  "Added to memory": "Añadido a la memoria",
  "Only what you confirmed. Attune records nothing on its own.": "Solo lo que tú confirmaste. Attune no registra nada por su cuenta.",
  "No signal, so only your saved places are searchable — nothing matched.": "Sin conexión, solo se pueden buscar tus lugares guardados, y nada coincidió.",
  "Nothing found for that.": "No se encontró nada para eso.",
  "Saved — it works offline now": "Guardado: ahora funciona sin conexión",
  "Map tiles cleared": "Mapas guardados borrados",
  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "Cada zona que miras se guarda, así que vuelve a funcionar sin conexión. También puedes descargar una zona antes de viajar. Buscar lugares necesita conexión; tus lugares guardados se pueden buscar sin ella.",
