  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "La IA de tu teléfono lo traduce por partes; los títulos, listas, tablas y números se quedan en su sitio. Los archivos largos tardan unos minutos.",
