  "Long-press the box and choose Paste": "Mantén pulsada la casilla y elige Pegar",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "Eso no es un enlace. Copia el enlace del vídeo (empieza por https://) y pégalo aquí.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} no permite descargar sus vídeos, así que Attune no puede guardarlos (Google Play retira las apps que lo hacen). Enlaces que funcionan: enlaces directos a vídeos, Google Drive, Dropbox, archive.org, Wikimedia Commons y páginas que muestran un archivo de vídeo normal.",
  "a streaming service": "un servicio de streaming",
  "this site": "este sitio",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "Es un enlace de emisión en directo (.m3u8): se transmite por partes y no se puede guardar como un solo archivo.",
  "Downloading works in the Android app.": "La descarga funciona en la app de Android.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive no entregó el archivo: asegúrate de que está compartido como \"Cualquier persona con el enlace\".",
  "This page plays a {site} video, which can't be downloaded.": "Esta página reproduce un vídeo de {site}, que no se puede descargar.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "Esta página transmite su vídeo por partes (HLS), que no se puede guardar como un solo archivo.",
  "No downloadable video was found on that page.": "No se encontró ningún vídeo descargable en esa página.",
  "That link didn't give a video file (the site sent {t}).": "Ese enlace no dio un archivo de vídeo (el sitio envió {t}).",
  "No downloadable video was found there.": "No se encontró ningún vídeo descargable ahí.",
  "Free includes 3 video downloads a day — Pro is unlimited": "Gratis incluye 3 descargas de vídeo al día; Pro no tiene límite",
  "Downloading — you can close Attune, it keeps going": "Descargando: puedes cerrar Attune, sigue en marcha",
  "The file was moved or deleted": "El archivo se movió o se eliminó",
