  "Ask anything about being here": "Pregunta lo que quieras sobre estar aquí",
  "e.g. the taxi driver won't turn the meter on, what do I say? / is this price fair for a carpet? / can I drink the tap water?": "p. ej. el taxista no quiere poner el taxímetro, ¿qué le digo? / ¿es justo este precio por una alfombra? / ¿se puede beber el agua del grifo?",
  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Sabe cómo funcionan de verdad las cosas aquí: precios justos, cobros abusivos habituales, qué se considera de mala educación. Te avisará cuando algo necesite datos en vivo que no puede tener sin conexión.",
