  "— a 3 GB model usually takes 10–40 s.": "— un modelo de 3 GB suele tardar 10–40 s.",
  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Este modelo es grande para este teléfono. Funciona, pero las respuestas llegan despacio y el teléfono se calienta. Para respuestas rápidas y fluidas usa Qwen 3.5 4B: el mismo árabe, lee fotos y es unas 3 veces más rápido.",
