  "Delete": "Eliminar",
  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "Los pesos instalados nunca se actualizan solos, así que una instrucción que funciona hoy funcionará igual dentro de un año. La huella digital demuestra exactamente qué archivo está respondiendo.",
  "Add any model": "Añadir cualquier modelo",
  "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   or   https://…/model.gguf": "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   o   https://…/model.gguf",
  "Any GGUF on Hugging Face as": "Cualquier GGUF de Hugging Face como",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", o un enlace https directo. Los modelos especializados y ajustados se instalan igual; el lector de fotos también se descarga si el repositorio incluye uno.",
  "How it answers": "Cómo responde",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "p. ej. Tengo una tienda pequeña en Egipto. Responde en árabe egipcio salvo que te escriba en inglés. Da los precios en EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Se guarda al tocar fuera del cuadro. Se queda en este teléfono.",
  "Web lookup": "Búsqueda web",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "Solo salen del teléfono la pregunta que buscas y las páginas que se abren; nunca tu conversación, tus archivos ni tu memoria.",
  "Hide network log": "Ocultar registro de red",
  "made ·": "realizadas ·",
  "blocked · this session": "bloqueadas · esta sesión",
  "Nothing has left the phone.": "No ha salido nada del teléfono.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "El modelo en sí nunca usa la red. El registro enumera cada conexión que la app hizo o rechazó, solo con el servidor y el motivo: la prueba de que «nada sale de este teléfono».",
  "Load a model to start": "Carga un modelo para empezar",
