  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "Caché KV INT4 + descarte por ventana deslizante, para que las conversaciones largas no crezcan sin límite.",
  "Storage:": "Almacenamiento:",
  "Compute": "Cómputo",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "El prefill se ejecuta donde el cómputo es más rápido y el decode donde hay más ancho de banda. Usar ambos eleva el ancho de banda útil de ~43 a 59 GB/s.",
  "Task adapters": "Adaptadores de tareas",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "Pequeños ajustes finos para cada tarea: lo que permite que un modelo del tamaño de un teléfono rinda por encima de lo esperado. Se cargan sobre el modelo base y ocupan unos pocos MB cada uno.",
