  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Conserva todo lo que hay en este teléfono y añade los chats, la memoria, los recordatorios y los días de ciclo de la copia. El libro de dinero solo se toma de la copia si este teléfono no tiene ninguno.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "Los {c} chats y los {l} movimientos de libro de este teléfono se reemplazarán por los de la copia. Puedes deshacerlo una vez, justo después.",
  "The backup's items will be added to this phone. You can undo this once, right after.": "Los elementos de la copia se añadirán a este teléfono. Puedes deshacerlo una vez, justo después.",
