  "Name the outcome; it fills in the path.": "Nombra el resultado y él rellena el camino.",
  "Huge window — compress for cost, not for fit.": "Ventana enorme: comprime por costo, no por falta de espacio.",
  "Direct phrasing; ask for reasoning explicitly.": "Formulación directa; pide el razonamiento de forma explícita.",
  "Structured reasoning; keep numbered steps.": "Razonamiento estructurado; mantén los pasos numerados.",
  "Strong multilingual — keep the source language.": "Muy multilingüe: mantén el idioma de origen.",
  "Concise by nature; over-compressing loses nuance.": "Conciso por naturaleza; comprimir demasiado pierde matices.",
  "Open weights; explicit instructions beat implied ones.": "Pesos abiertos; las instrucciones explícitas funcionan mejor que las implícitas.",
  "Long documents are its strength; keep headings.": "Su punto fuerte son los documentos largos; conserva los encabezados.",
  "Code context competes for the window — trim prose first.": "El código compite por la ventana: recorta primero la prosa.",
  "A search tool — keep the sources, cut the styling.": "Es una herramienta de búsqueda: conserva las fuentes y quita el estilo.",
  "Tight. Cut everything that isn't the instruction.": "Ajustado. Quita todo lo que no sea la instrucción.",
  "Room for a short history, not a long one.": "Hay espacio para un historial corto, no para uno largo.",
  "Same window; better at using what's in it.": "Misma ventana; aprovecha mejor lo que hay en ella.",
  "Ed25519": "Ed25519",
  "Activated offline — it will bind to this device the next time there's a connection.": "Activada sin conexión: se vinculará a este dispositivo la próxima vez que haya conexión.",
