  "refunds and shared keys": "reembolsos y claves compartidas",
  "Qwen3.6 35B-A3B · long context": "Qwen3.6 35B-A3B · contexto largo",
  "Write": "Escribir",
  "Review": "Revisar",
  "Long documents": "Documentos largos",
  "The strongest dense model that still fits a 32 GB machine. Quantisation-aware trained, so 4-bit costs almost nothing in quality here.": "El modelo denso más potente que aún cabe en un equipo de 32 GB. Entrenado con cuantización, así que aquí los 4 bits casi no cuestan calidad.",
  "26B-class answers with under 4B active per token. The best quality-per-second on a strong laptop.": "Respuestas de clase 26B con menos de 4B activos por token. La mejor calidad por segundo en un portátil potente.",
  "Reads text, images and audio. Comfortable on a laptop or a 16 GB phone.": "Lee texto, imágenes y audio. Cómodo en un portátil o en un teléfono de 16 GB.",
  "Photos": "Fotos",
  "The strongest sub-10B model measured anywhere, and the best of these at reading documents and photographs.": "El mejor modelo de menos de 10B medido en cualquier parte, y el mejor de estos para leer documentos y fotografías.",
  "The one to have if your phone can hold it. Reads photographs of documents and receipts, handles Arabic and English, and a fifth bit of precision over the smaller build is a real quality difference you can feel on long answers.": "El ideal si tu teléfono puede con él. Lee fotos de documentos y recibos, maneja árabe e inglés, y un quinto bit de precisión sobre la versión más pequeña es una diferencia de calidad real que se nota en respuestas largas.",
  "Text, images and audio on a flagship phone. Pick this over the Qwen if you want voice notes read back to you.": "Texto, imágenes y audio en un teléfono de gama alta. Elígelo antes que el Qwen si quieres que te lean las notas de voz.",
  "Voice": "Voz",
  "The sweet spot on an ordinary modern phone. Everything the app does, in under 3 GB.": "El punto ideal en un teléfono moderno normal. Todo lo que hace la app, en menos de 3 GB.",
  "The same 4B model squeezed 10% smaller for a 4 GB phone. Slightly slower on older chips, and worth it to get the 4B rather than dropping to the 2B.": "El mismo modelo de 4B comprimido un 10 % más para un teléfono de 4 GB. Algo más lento en chips antiguos, y vale la pena para quedarte con el de 4B en vez de bajar al de 2B.",
  "Runs on a cheap phone and still reads photographs. Short answers are good; long reasoning is where you'll notice the size.": "Funciona en un teléfono barato y aun así lee fotografías. Las respuestas cortas salen bien; con razonamientos largos es donde notarás el tamaño.",
  "For a phone that can't hold anything else. Useful for tidying and shortening text; don't ask it to reason.": "Para un teléfono que no puede con nada más. Sirve para ordenar y acortar textos; no le pidas que razone.",
  "This device is below what any local model needs": "Este dispositivo está por debajo de lo que necesita cualquier modelo local",
  "Everything here runs on your own hardware, and the smallest useful model wants about 2 GB of memory to itself. Attune's tools that don't need a model still work.": "Todo aquí se ejecuta en tu propio equipo, y el modelo útil más pequeño necesita unos 2 GB de memoria solo para él. Las herramientas de Attune que no necesitan un modelo siguen funcionando.",
  "Neural Engine": "Neural Engine",
  "prefill + decode": "prefill + decode",
  "Rewrite": "Reescribir",
  "Field docs": "Documentos de campo",
  "It declined or dodged the question.": "Rehusó o esquivó la pregunta.",
  "Say why you need it and what you'll do with it, and ask for the part it can answer.": "Explica por qué lo necesitas y qué harás con ello, y pídele la parte que sí puede responder.",
  "It hedged instead of committing.": "Dudó en lugar de comprometerse.",
  "Ask it to pick one and defend it: “Choose the single best option and say why the others lose.”": "Pídele que elija una y la defienda: «Elige la mejor opción y explica por qué las demás pierden».",
  "That's a generic answer — it could have been written without your details.": "Es una respuesta genérica: podría haberse escrito sin tus datos.",
  "Give it your actual numbers and constraints, and ask it to redo the answer using only those.": "Dale tus cifras y restricciones reales y pídele que rehaga la respuesta usando solo esas.",
  "It spent the answer restating your question.": "Gastó la respuesta repitiendo tu pregunta.",
  "Tell it to skip the recap and start at the answer.": "Dile que omita el resumen y empiece por la respuesta.",
  "It looks cut off.": "Parece cortada.",
  "Ask it to continue from where it stopped, not to start again.": "Pídele que continúe desde donde se detuvo, no que empiece de nuevo.",
  "It asked you a question instead of answering.": "Te hizo una pregunta en vez de responder.",
  "Answer the question inside your next prompt so it can't stall again.": "Responde a la pregunta dentro de tu siguiente mensaje para que no pueda volver a frenarse.",
  "This repeats an earlier answer — the conversation is going in circles.": "Esto repite una respuesta anterior: la conversación da vueltas en círculo.",
  "Change the angle: ask for what it would do differently, or give it a constraint it hasn't had.": "Cambia el enfoque: pregúntale qué haría de otra forma o dale una restricción que aún no haya tenido.",
  "Sharpen": "Afinar",
  "narrower and more specific — pin it down": "más acotado y específico: concrétalo",
  "Widen": "Ampliar",
  "step back and ask for options you haven't considered": "da un paso atrás y pide opciones que no hayas considerado",
  "Press": "Presionar",
  "challenge the answer and make it defend or correct itself": "cuestiona la respuesta y haz que la defienda o se corrija",
  "Reads clean structure well — tags mark where context ends and the task begins.": "Lee bien las estructuras limpias: las etiquetas marcan dónde acaba el contexto y empieza la tarea.",
  "Turn on Extended Thinking for hard reasoning.": "Activa el pensamiento extendido para razonamientos difíciles.",
  "Does best when you name the outcome and let it choose the path.": "Funciona mejor si nombras el resultado y le dejas elegir el camino.",
  "Let the router pick, or choose Thinking for complex tasks.": "Deja que el enrutador elija, o elige Thinking para tareas complejas.",
  "Wants direct, concise input and defaults to short answers.": "Prefiere entradas directas y concisas, y responde corto por defecto.",
  "Use Pro; enable Deep Research for multi-source work.": "Usa Pro; activa Deep Research para trabajos con varias fuentes.",
  "Handles direct, conversational prompts; ask for reasoning explicitly.": "Maneja bien indicaciones directas y conversacionales; pide el razonamiento de forma explícita.",
  "Turn on Think mode for step-by-step reasoning.": "Activa el modo Think para razonar paso a paso.",
  "Strong at structured reasoning and code.": "Es fuerte en razonamiento estructurado y código.",
  "Enable DeepThink (R1) for reasoning-heavy work.": "Activa DeepThink (R1) para trabajos de mucho razonamiento.",
  "Runs autonomously across many steps — give a goal, constraints, and a deliverable.": "Trabaja de forma autónoma en muchos pasos: dale un objetivo, restricciones y un entregable.",
  "Give it files/links up front; let it run async.": "Dale los archivos o enlaces desde el principio y déjalo ejecutarse en segundo plano.",
  "A search engine first — told which sources to trust and to cite them.": "Ante todo es un buscador: indícale en qué fuentes confiar y que las cite.",
  "Pick Pro or Research mode; always check the citations.": "Elige el modo Pro o Research; comprueba siempre las citas.",
  "Only answers from your uploaded sources — cite passages, admit gaps.": "Solo responde con tus fuentes subidas: cita pasajes y admite lagunas.",
  "Upload sources first; try an Audio Overview.": "Sube primero las fuentes; prueba un Audio Overview.",
  "Wants a dense visual description plus parameters.": "Quiere una descripción visual densa más parámetros.",
