  "3 templates · 5 history items": "3 plantillas · 5 elementos de historial",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B de conocimiento, con 3B haciendo el trabajo en cada token: respuestas casi de primer nivel a una velocidad que un portátil puede mantener. Un modelo de mezcla de expertos mantiene todos los expertos en memoria aunque pocos se ejecuten por token, así que necesita la RAM de un 35B y el cómputo de un 3B.",
  "A bigger length budget for reports, plans and analysis.": "Un mayor margen de longitud para informes, planes y análisis.",
  "Ask it as much as you like — no daily limit": "Pregúntale cuanto quieras: sin límite diario",
  "Your phone reports {n} GB of memory": "Tu teléfono indica {n} GB de memoria",
