  "Documents, fleet records, copilot, every domain pack": "Documentos, registros de flota, copiloto, todos los paquetes de dominio",
  "Small enough to download on mobile data if you need to.": "Lo bastante pequeño para descargarlo con datos móviles si hace falta.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "Es un modelo grande para un teléfono. Funcionará, pero irá notablemente más lento cuando el teléfono se caliente: mantén las respuestas cortas o elige el más pequeño.",
  "Every tool, and all 31 country packs": "Todas las herramientas y los 31 paquetes de país",
  "Finds what you promised people, from your own words": "Encuentra lo que prometiste a la gente, a partir de tus propias palabras",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Aleatoriedad fija, para que un flujo de trabajo dé siempre el mismo resultado.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Búsqueda web gratuita: DuckDuckGo, Bing y Mojeek a la vez; luego se leen completas las páginas principales, así que las respuestas salen de pasajes reales.",
  "Free · no key": "Gratis · sin clave",
  "Installing… {p}%": "Instalando… {p} %",
  "It remembers everything and can search it": "Lo recuerda todo y puede buscar en ello",
  "Learns your vocabulary and writes the way you do": "Aprende tu vocabulario y escribe como tú",
  "No account, no sign-in, nothing uploaded": "Sin cuenta, sin iniciar sesión, nada se sube",
  "Running": "En marcha",
  "Loading the model…": "Cargando el modelo…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Nada en la app puede acceder a internet: ni búsqueda web, ni mapas, ni descargas. El modelo y todo lo que hay en el teléfono siguen funcionando.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "El modelo razona primero en cada pregunta. Claramente mejor en problemas difíciles, pero en un teléfono la respuesta empieza entre 30 y 90 s después. Desactivado: toca «Pensar» solo en las preguntas que lo necesiten.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "El mismo modelo de abajo, con memoria para contener de una vez un libro entero de contexto. En un equipo de 48 GB, la RAM sobrante rinde más en contexto que en precisión: puedes darle un contrato entero o un año de notas y lo mantiene todo a la vista.",
  "The whole assistant, on your device": "Todo el asistente, en tu dispositivo",
  "Works entirely offline. No account, ever.": "Funciona totalmente sin conexión. Nunca hay cuenta.",
