  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Las notificaciones de Attune están desactivadas: toca para permitirlas o los recordatorios no podrán aparecer.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "Los recordatorios pueden llegar hasta 10 minutos tarde. Toca para permitir «Alarmas y recordatorios» a Attune y que suenen en punto.",
