  "Load weight confirmed (drawing, weighbridge or manufacturer) — not guessed": "Peso de la carga confirmado (plano, báscula o fabricante), no estimado",
  "Radius and boom length checked on the load chart for the exact configuration (counterweight, outrigger spread)": "Radio y longitud de pluma comprobados en la tabla de carga para la configuración exacta (contrapeso, apertura de estabilizadores)",
