  "Worked out on the phone — exact, instant, no model": "Calculado en el teléfono: exacto, instantáneo, sin modelo",
  "Ask the model": "Preguntar al modelo",
  "unusually slow — why?": "inusualmente lento: ¿por qué?",
  "Send this report": "Enviar este informe",
  "Not available in this build": "No disponible en esta versión",
  "The phone is hot — it slows the processor down on purpose. Let it cool, take it out of its case, don't charge while asking.": "El teléfono está caliente y reduce a propósito la velocidad del procesador. Déjalo enfriar, quítale la funda y no lo cargues mientras preguntas.",
  "Battery saver is on — it caps the processor. Turn it off while using Attune.": "El ahorro de batería está activado y limita el procesador. Desactívalo mientras uses Attune.",
  "Free memory is low for this model — close other apps (games, camera, many browser tabs).": "Queda poca memoria libre para este modelo: cierra otras apps (juegos, cámara, muchas pestañas del navegador).",
  "The model is read from storage instead of RAM — update to the latest Attune APK (it loads the model into RAM).": "El modelo se lee desde el almacenamiento en lugar de la RAM: actualiza al último APK de Attune (carga el modelo en la RAM).",
  "The engine is using its slowest processor path (no dotprod). Send this report.": "El motor usa su vía de procesador más lenta (sin dotprod). Envía este informe.",
  "The phone is critically hot — Attune stops an answer in progress and keeps what was written. Let it cool for a few minutes.": "El teléfono está a una temperatura crítica: Attune detiene la respuesta en curso y conserva lo escrito. Déjalo enfriar unos minutos.",
  "The phone is very hot — Attune waits up to 20 seconds before each new answer so it can cool, and uses fewer threads the next time the model starts.": "El teléfono está muy caliente: Attune espera hasta 20 segundos antes de cada respuesta nueva para que se enfríe, y usa menos hilos la próxima vez que arranque el modelo.",
  "The phone is getting warm — long answers may slow down soon. Short breaks between answers keep it fast.": "El teléfono se está calentando: las respuestas largas podrían ralentizarse pronto. Con pequeñas pausas entre respuestas se mantiene rápido.",
  "Only {n} threads are used for writing.": "Solo se usan {n} hilos para escribir.",
  "This is a big model for a phone — Qwen 3.5 4B is about 2–3× faster.": "Es un modelo grande para un teléfono: Qwen 3.5 4B es unas 2–3 veces más rápido.",
  "Nothing obvious — the phone may have slowed Attune while it was in the background. The new APK keeps it at full speed while writing.": "Nada evidente: puede que el teléfono haya ralentizado Attune mientras estaba en segundo plano. El nuevo APK lo mantiene a toda velocidad al escribir.",
  "Nothing is holding it back.": "Nada lo está frenando.",
  "Money tools": "Herramientas de dinero",
  "Gemma 4 E2B · fast engine (GPU)": "Gemma 4 E2B · motor rápido (GPU)",
  "Gemma 4 E4B · fast engine (GPU)": "Gemma 4 E4B · motor rápido (GPU)",
  "The fast one. Runs on the phone's graphics chip: the first words appear in under a second and it writes faster than you can read. Reads photos, English and Arabic. For hard reasoning, the E4B below is stronger.": "El rápido. Se ejecuta en el chip gráfico del teléfono: las primeras palabras aparecen en menos de un segundo y escribe más rápido de lo que puedes leer. Lee fotos, inglés y árabe. Para razonamientos difíciles, el E4B de abajo es más potente.",
  "The stronger fast one: noticeably better answers than the E2B, still on the graphics chip — first words in about a second, then roughly 20–45 words a second on a flagship.": "El rápido y más potente: respuestas claramente mejores que el E2B, también en el chip gráfico: primeras palabras en cerca de un segundo y luego entre 20 y 45 palabras por segundo en un gama alta.",
  "Stronger ·": "Más potente ·",
  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick answers use Gemma 4 E2B on the fast engine — reads photos, first words in about a second.": "Este modelo es grande para este teléfono. Funciona, pero las respuestas llegan despacio y el teléfono se calienta. Para respuestas rápidas usa Gemma 4 E2B en el motor rápido: lee fotos y las primeras palabras salen en cerca de un segundo.",
  "Fast engine on the graphics chip": "Motor rápido en el chip gráfico",
  "Fast engine on the CPU": "Motor rápido en la CPU",
  "multi-token prediction on": "predicción de varios tokens activada",
  "Use the graphics chip": "Usar el chip gráfico",
  "On: the model runs on the GPU — first words in about a second. Off: the CPU, slower, only for phones whose GPU driver misbehaves.": "Activado: el modelo se ejecuta en la GPU, con las primeras palabras en cerca de un segundo. Desactivado: la CPU, más lenta, solo para teléfonos cuyo controlador de GPU falla.",
  "Gemma 4 E2B on the graphics chip: first words in about a second, many times faster than this engine. {s} GB, once.": "Gemma 4 E2B en el chip gráfico: primeras palabras en cerca de un segundo, muchas veces más rápido que este motor. {s} GB, una sola vez.",
  "The fast engine is running on the CPU, not the graphics chip — turn on “Use the graphics chip” above. If it switched itself off, the phone's GPU driver refused it: send this report.": "El motor rápido se está ejecutando en la CPU, no en el chip gráfico: activa «Usar el chip gráfico» arriba. Si se desactivó solo, el controlador de GPU del teléfono lo rechazó: envía este informe.",
  "The biggest speed-up on this phone is the fast engine: Gemma 4 E2B on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "La mayor aceleración en este teléfono es el motor rápido: Gemma 4 E2B en el chip gráfico, con las primeras palabras en cerca de un segundo. Toca «Cambiar al motor rápido» arriba.",
  "The GPU would not start, so the fast engine is on the CPU. ": "La GPU no arrancó, así que el motor rápido está en la CPU. ",
  "Last time, starting the fast engine on the GPU closed the app. It is on the CPU now; you can try the GPU again in Engine → Speed.": "La última vez, arrancar el motor rápido en la GPU cerró la app. Ahora está en la CPU; puedes probar la GPU de nuevo en Motor → Velocidad.",
  "Preparing the fast engine (the first start on the GPU takes longest)": "Preparando el motor rápido (el primer arranque en la GPU es el más lento)",
  "Change it… e.g. “also show the total in EGP”": "Cámbialo… p. ej. «muestra también el total en EGP»",
