  "What are the key points?": "¿Cuáles son los puntos clave?",
  "Checklist: what every answer must satisfy (one per line, optional)": "Lista de control: lo que debe cumplir toda respuesta (una por línea, opcional)",
  "Facts the AI should know (prices, rules, terms — optional)": "Datos que la IA debe conocer (precios, reglas, condiciones; opcional)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Separa los temas con una línea vacía. Solo se usan los párrafos que encajan con la pregunta, así que puede ser largo.",
  "Facts": "Datos",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "También ejecuta este pequeño programa en tu teléfono (sin conexión, en una caja cerrada: sin internet, sin archivos, sin acceso a la app)",
  "Edit or improve my CV": "Editar o mejorar mi CV",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Indica qué añadir o cambiar («añade mi trabajo en el Hospital Dar Al Fouad como enfermero, 2019–2022», «cambia mi teléfono por …»), o déjalo vacío y solo hazlo más profesional. Ves el resultado antes de conservarlo.",
  "What should be added or changed? (optional)": "¿Qué hay que añadir o cambiar? (opcional)",
  "Apply my change": "Aplicar mi cambio",
  "Change + make it professional": "Cambiar + hacerlo profesional",
  "New version": "Nueva versión",
