  "✓ Ran without errors.": "✓ Se ejecutó sin errores.",
  "The fix did not match the code.": "La corrección no coincidía con el código.",
  "The model answered without code.": "El modelo respondió sin código.",
  "The fix deleted the tests — refused.": "La corrección borró las pruebas: rechazada.",
  "The model answered without any code — try asking again in other words.": "El modelo respondió sin ningún código: prueba a pedirlo de nuevo con otras palabras.",
  "A picture — Studio draws it on this phone": "Una imagen: Estudio la dibuja en este teléfono",
  "Another version": "Otra versión",
  "Could not open that picture": "No se pudo abrir esa imagen",
  "Could not save": "No se pudo guardar",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Calidad fotográfica actual en 4 pasos: personas, lugares, productos y texto en las imágenes. También edita una foto que le des («hazla de noche», «quita el coche»).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Describe la imagen, en árabe o en inglés, p. ej. «una faluca en el Nilo al atardecer»",
  "Developing the picture…": "Revelando la imagen…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Descárgalo con Wi-Fi. Después, las imágenes se crean sin ninguna conexión a internet.",
  "Draw it": "Dibujarla",
  "Draw it in Studio": "Dibujarla en Estudio",
  "A place — Maps finds it": "Un lugar: Mapas lo encuentra",
  "Show on the map": "Mostrar en el mapa",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Dibujar en el chip gráfico (más rápido; se desactiva solo si falla el controlador)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Dibujar en la GPU falló, así que Attune cambió Estudio a la CPU. ",
  "Drawing — step {n} of {t}": "Dibujando: paso {n} de {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Cada imagen la crea un proceso de motor independiente: al terminar, toda su memoria vuelve al teléfono. No se sube nada.",
  "Edit a photo": "Editar una foto",
  "Edit it": "Editarla",
  "Edit this": "Editar esto",
  "GB, once": "GB, una sola vez",
  "Install the picture model first (Studio).": "Instala primero el modelo de imágenes (Estudio).",
  "Install the sharpening model first (Studio).": "Instala primero el modelo de nitidez (Estudio).",
