  "Save to gallery": "Guardar en la galería",
  "Saved to {w}": "Guardado en {w}",
  "Saving to the gallery needs Android 10 or newer — use Share instead.": "Guardar en la galería requiere Android 10 o posterior: usa Compartir.",
  "Saving…": "Guardando…",
  "Sharpening ×4": "Nitidez ×4",
