  "Square": "Cuadrada",
  "Starting the download…": "Iniciando la descarga…",
  "Starting the picture engine…": "Iniciando el motor de imágenes…",
  "Studio works in the Android app.": "Estudio funciona en la app de Android.",
  "The chat model was paused to make room, and is loading again.": "El modelo del chat se pausó para hacer sitio y se está cargando de nuevo.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "Este APK aún no tiene motor de imágenes: vendrá con el próximo APK compilado en GitHub.",
  "This build draws on the CPU.": "Esta versión dibuja en la CPU.",
  "This build of the app has no picture engine yet.": "Esta versión de la app aún no tiene motor de imágenes.",
  "This phone has {n} GB — it may be too little for pictures.": "Este teléfono tiene {n} GB: puede ser poco para imágenes.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Esta versión de Attune no tiene motor de imágenes en el chip gráfico, así que las imágenes se dibujan en la CPU (más lento). Una actualización lo añadirá.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "El motor de imágenes dejó de responder al cargar el modelo, así que se detuvo. Motor → Registro del motor muestra sus últimas líneas: envíalas a soporte.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "El controlador de GPU de este teléfono no respondió, así que las imágenes se dibujan en la CPU (más lento).",
  "What should change? e.g. “make it night, with the street lights on”": "¿Qué debe cambiar? p. ej. «hazla de noche, con las farolas encendidas»",
  "Write a fuller description first (better pictures; uses the chat model)": "Escribe antes una descripción más completa (mejores imágenes; usa el modelo del chat)",
  "Writing a fuller description…": "Escribiendo una descripción más completa…",
  "needs {n} GB RAM": "necesita {n} GB de RAM",
  "{m} is ready": "{m} está listo",
  "×4 sharper": "×4 más nítida",
  "drawn on the {b} in {t}": "dibujada en {b} en {t}",
  "sharpened on the {b} in {t}": "afinada en {b} en {t}",
  "Newest": "Más recientes",
  "stopped a repeat": "evitó una repetición",
  "Checked by running code on this phone": "Comprobado ejecutando código en este teléfono",
  "It printed:": "Imprimió:",
  "fixed {n}×": "corregido {n}×",
  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "Aún no he conseguido que pasen todas las pruebas; esta es la versión más cercana. Toca «Probar y corregir en Código» para seguir.",
  "Working it out as a program…": "Resolviéndolo como un programa…",
  "Fixing the program and running it again…": "Corrigiendo el programa y ejecutándolo de nuevo…",
  "Checked by running code — writing the answer…": "Comprobado ejecutando código: escribiendo la respuesta…",
  "Looking at the photo…": "Mirando la foto…",
  "Searching the web…": "Buscando en la web…",
  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · alta calidad",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "Las mejores imágenes que puede crear este teléfono: la versión de 8 bits de FLUX.2 klein, con más detalle y rostros, manos y texto más limpios. También edita tus fotos mediante instrucciones.",
  "That file is too large (15 MB at most)": "Ese archivo es demasiado grande (15 MB como máximo)",
  "What's in this file? Summarise what matters.": "¿Qué contiene este archivo? Resume lo que importa.",
  "Checked — the reviewer fixed a mistake": "Comprobado: el revisor corrigió un error",
  "{n} tries disagreed — weighed and checked": "{n} intentos discrepaban: ponderados y comprobados",
  "{v} of {n} tries agreed · checked": "{v} de {n} intentos coincidieron · comprobado",
