  "Wrong? Teach the right answer": "¿Mal? Enséñale la respuesta correcta",
  "What should it have said? Chat will answer this way next time you ask something like it.": "¿Qué debería haber dicho? El chat responderá así la próxima vez que preguntes algo parecido.",
  "The right answer": "La respuesta correcta",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "Por qué (opcional), p. ej. «la canica se cae cuando se da la vuelta al vaso»",
  "Learned — Chat will use this on similar questions": "Aprendido: el chat lo usará en preguntas parecidas",
  "That is the same as the answer — nothing to learn": "Es igual que la respuesta: no hay nada que aprender",
  "Thinking it through…": "Pensándolo bien…",
