  "Computed from your file — writing the answer…": "Calculado desde tu archivo: escribiendo la respuesta…",
  "Python is not in this build, so the file can't be computed on.": "Python no está en esta versión, así que no se puede calcular sobre el archivo.",
  "What should it have said? Attune double-checks your correction first, and learns it only if it holds up.": "¿Qué debería haber dicho? Attune comprueba primero tu corrección y la aprende solo si se sostiene.",
  "Checked — I don't think the correction is right": "Comprobado: creo que la corrección no es correcta",
  "Checked — your correction is partly right": "Comprobado: tu corrección es en parte correcta",
  "Couldn't confirm your correction": "No se pudo confirmar tu corrección",
