  "Edit my correction": "Editar mi corrección",
  "Checking…": "Comprobando…",
  "Check & teach": "Comprobar y enseñar",
  "Double-checking your correction…": "Comprobando tu corrección…",
  "Checking your correction by computing it…": "Comprobando tu corrección mediante cálculo…",
  "The checks disagree — one more look…": "Las comprobaciones discrepan: una mirada más…",
  "Checked — you're right. Learned for next time": "Comprobado: tienes razón. Aprendido para la próxima vez",
  "Learned — Chat will answer your way on similar questions": "Aprendido: el chat responderá a tu manera en preguntas parecidas",
  "Could not check it: {e}": "No se pudo comprobar: {e}",
  "Could not check it (no answer from the model).": "No se pudo comprobar (el modelo no respondió).",
  "The phone's storage for Business is full — export a table to CSV and delete old records.": "El almacenamiento de Negocio en el teléfono está lleno: exporta una tabla a CSV y borra registros antiguos.",
  "Created — {n} tables": "Creado: {n} tablas",
  "Deleted": "Eliminado",
  "Your own ERP: customers, stock, jobs, invoices — whatever your business tracks. Change any table or column later, like Microsoft Access.": "Tu propio ERP: clientes, existencias, trabajos, facturas, lo que tu negocio controle. Cambia cualquier tabla o columna después, como en Microsoft Access.",
  "{n} tables": "{n} tablas",
  "Active": "Activo",
  "Trial": "Prueba",
  "The model didn't produce a usable design. Try again, describe it differently, or start from a template.": "El modelo no generó un diseño utilizable. Inténtalo de nuevo, descríbelo de otra forma o parte de una plantilla.",
  "This is the design. You can change every table and column after creating it.": "Este es el diseño. Puedes cambiar cada tabla y columna después de crearlo.",
