  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "Entrégalo a tu equipo como una app: un solo archivo con todos los datos dentro, que se abre en el navegador de cualquier teléfono u ordenador, sin necesidad de Attune. Cuando haya que cambiar algo, abre el archivo aquí (Negocio → Abrir un archivo de app), díselo a la IA y devuelve la nueva app.",
  "Export as an app": "Exportar como app",
  "Excel workbook (all tables)": "Libro de Excel (todas las tablas)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "El motor de imágenes se detuvo antes de terminar la imagen: puede que Android lo haya cerrado para liberar memoria. Prueba «Borrador rápido» o cierra otras apps y vuelve a intentarlo.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "No se pudo crear la imagen. Abre Motor → Registro del motor y envíame lo que dice.",
  "Multi-token prediction (faster writing)": "Predicción de varios tokens (escritura más rápida)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "Desactivada por defecto: en algunos teléfonos duplica palabras y dígitos («ElEl es es», «20205»). Actívala solo si las respuestas siguen siendo correctas.",
  "The last picture didn't finish:": "La última imagen no se terminó:",
