  "Connected {n} fields — Undo (top) puts them back": "Se conectaron {n} campos: Deshacer (arriba) los devuelve",
  "Connect the tables": "Conectar las tablas",
  "Something went wrong on this screen.": "Algo salió mal en esta pantalla.",
  "Your chats and data are safe. Try again — if it keeps happening, send me this message.": "Tus chats y datos están a salvo. Inténtalo de nuevo; si sigue pasando, envíame este mensaje.",
