  "Studio Turbo": "Estudio Turbo",
  "Studio Pro": "Estudio Pro",
  "Studio Pro HD": "Estudio Pro HD",
  "Turbo · about 1 min": "Turbo · cerca de 1 min",
  "Studio Turbo+": "Estudio Turbo+",
  "Recommended for your phone": "Recomendado para tu teléfono",
  "Studio Ultra": "Estudio Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · la mejor calidad, lento · {s} GB",
  "best quality, slow": "la mejor calidad, lento",
  "fastest pictures": "las imágenes más rápidas",
  "a graphics card with 8 GB or more: the most capable model": "una tarjeta gráfica de 8 GB o más: el modelo más capaz",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "El modelo más capaz: texto dentro de las imágenes, escenas recargadas, personas. Lento en un teléfono (unos 10 minutos por imagen), rápido en un ordenador con tarjeta gráfica. Necesita 12 GB de RAM.",
  "about {s} s a picture": "unos {s} s por imagen",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB o más y núcleos rápidos: el modelo XL, más nítido, en un solo paso",
  "not enough free storage or speed for the XL model": "no hay almacenamiento libre ni velocidad suficientes para el modelo XL",
  "the fast model fits this phone's memory": "el modelo rápido cabe en la memoria de este teléfono",
  "little memory or slow cores: smaller pictures, still clear": "poca memoria o núcleos lentos: imágenes más pequeñas, aún nítidas",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · unos 20 s · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Más rápido y nítido que Turbo, con mejor ajuste a lo que pides: unos 20 segundos por imagen en la CPU. 512 px. Para teléfonos con 8 GB de RAM o más.",
  "Pro · best quality": "Pro · la mejor calidad",
  "Pro on this phone's CPU: 10–20 min a picture": "Pro en la CPU de este teléfono: 10–20 min por imagen",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "El chip gráfico de este teléfono no funciona con Estudio, así que el modelo Pro tardaría 10–20 minutos por imagen en la CPU. Estudio Turbo crea una imagen en cerca de un minuto.",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "Imágenes rápidas en cualquier teléfono: cerca de un minuto sin chip gráfico, segundos con uno. 512 px: ideal para ideas, borradores y publicaciones.",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "La mejor calidad fotográfica: personas, lugares, productos y texto en las imágenes, a 1024 px. También edita una foto que le des («hazla de noche», «quita el coche»). Necesita un chip gráfico que funcione: en la CPU una imagen tarda 10–20 minutos.",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "Estudio Pro a plena precisión: más detalle y rostros, manos y texto más limpios. También edita tus fotos mediante instrucciones. Necesita un chip gráfico que funcione y 12 GB de RAM.",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "Sigue trabajando; no se ha atascado nada. Turbo tarda 1–2 minutos en la CPU. Mantén Attune abierto; Detener lo cancela.",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "Sigue trabajando; no se ha atascado nada. Sin chip gráfico, una imagen Pro tarda 10–20 minutos (las ediciones, más). Para ir rápido, elige Turbo. Mantén Attune abierto; Detener lo cancela.",
  "Delete this chat?": "¿Eliminar este chat?",
  "This can't be undone.": "Esto no se puede deshacer.",
  "Delete this reminder?": "¿Eliminar este recordatorio?",
  "Delete this project?": "¿Eliminar este proyecto?",
