  "Spark (helper)": "Spark (ayudante)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "Solo funciona con Spark, Glow, Core y Zenith, no con el modelo en uso.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Descarga Spark como ayudante (unos 0,5 GB, una sola vez). Funciona con Glow, Core y Zenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "Es un modelo grande para un teléfono: Core es unas 2–3 veces más rápido.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "El modelo más potente que puede ejecutar un teléfono de 12 GB: respuestas de experto y el mejor leyendo documentos y fotos.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "Core un 10 % más pequeño para un teléfono de 4 GB: mejor que Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "Funciona en un teléfono económico y aun así lee fotos. Buenas respuestas cortas; los razonamientos largos delatan su tamaño.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "Para un teléfono que no puede con nada más: ordenar y acortar textos. No para razonar.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "La mayor aceleración en este teléfono es el motor rápido: Blaze en el chip gráfico, con las primeras palabras en cerca de un segundo. Toca «Cambiar al motor rápido» arriba.",
