  "Put the ask after the data (Gemini/GPT guidance)": "Pon la petición después de los datos (pautas de Gemini/GPT)",
  "Define the output shape explicitly": "Define de forma explícita la forma del resultado",
  "Name the goal so the model reasons toward it": "Nombra el objetivo para que el modelo razone hacia él",
  "Specificity → fewer misinterpretations": "Precisión → menos malentendidos",
  "Goal-framing beats tone adjectives alone": "Plantear el objetivo funciona mejor que solo adjetivos de tono",
  "Data first, question last improves grounding": "Datos primero y pregunta al final: respuestas más ancladas en la fuente",
  "Role-free outcome framing (2026 guidance)": "Describir el resultado sin asignar roles (pautas 2026)",
  "Explicit output shape reduces rework": "Una forma de resultado explícita reduce rehacer trabajo",
  "Goal + constraint framing produces usable scripts": "Objetivo + restricciones dan guiones que se pueden usar",
  "Stated criteria prevent generic pro/con lists": "Fijar criterios evita listas genéricas de pros y contras",
  "Concrete constraints beat generic advice": "Las restricciones concretas superan a los consejos genéricos",
  "Time constraints force actionable plans": "Los límites de tiempo obligan a planes que se pueden cumplir",
  "Matching to the posting outperforms templates": "Ajustarse a la oferta de empleo supera a las plantillas",
  "Role-specific prompting beats generic question lists": "Las peticiones según el puesto superan a las listas genéricas de preguntas",
  "Source-anchored prompts reduce invented detail": "Anclar la petición a una fuente reduce los detalles inventados",
  "Constraints up front prevent generic travel advice": "Dar las restricciones al principio evita consejos de viaje genéricos",
  "Explaining the 'why' improves targeting (Anthropic)": "Explicar el «porqué» mejora la precisión (Anthropic)",
  "Search tools need source + recency constraints": "Las herramientas de búsqueda necesitan límites de fuente y de actualidad",
  "Constraints up front prevent generic answers": "Dar las restricciones al principio evita respuestas genéricas",
  "Active recall outperforms re-reading": "Recordar activamente funciona mejor que releer",
  "Sectioned output aids comprehension": "Un resultado por secciones se entiende mejor",
  "Explicit critique requests beat 'what do you think'": "Pedir una crítica explícita supera a «¿qué te parece?»",
  "Naming review axes prevents shallow feedback": "Nombrar los aspectos a revisar evita comentarios superficiales",
  "Include context + attempted fixes for accuracy": "Incluye el contexto y lo que ya probaste para más precisión",
  "Section-by-section output beats 'write a page'": "Escribir sección por sección supera a «escribe una página»",
  "Persona-specific prompts improve targeting": "Las peticiones para un público concreto mejoran la precisión",
  "Stating criteria prevents generic pro/con lists": "Indicar criterios evita listas genéricas de pros y contras",
  "Level-setting improves explanation fit": "Fijar el nivel hace que la explicación encaje mejor",
  "Specifying length prevents rambling summaries": "Indicar la extensión evita resúmenes que se alargan",
  "Ask to implement, not 'suggest changes' (Anthropic)": "Pide que lo implemente, no «sugiere cambios» (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "Los modelos de razonamiento rinden mejor con un alcance claro y sin ejemplos",
  "Name every state so nothing is left ambiguous": "Nombra cada estado para que nada quede ambiguo",
  "Natural language + explicit variety works on GPT": "Lenguaje natural + pedir variedad explícitamente funciona en GPT",
  "Outcome framing beats feature lists": "Describir el resultado supera a las listas de funciones",
  "Gemini prefers direct, constrained prompts": "Gemini prefiere peticiones directas y acotadas",
  "Short + specific tone yields natural output": "Un tono breve y concreto da un resultado natural",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "Cadena de pensamiento: +~40 % de media en razonamiento difícil (Wei et al.); MultiArith del 18 % al 79 %. No la uses con modelos de razonamiento: poca mejora y más espera.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "De 1 a 5 ejemplos (few-shot) suben la precisión en tareas de patrones hasta un +43 %; mejor en modelos sin razonamiento como Gemini. No añadas ejemplos en tareas de puro razonamiento: pueden empeorar.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: describe cómo es un buen resultado; dar demasiadas instrucciones mete ruido en los modelos actuales.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "Práctica de 2026: fija cuánto debe pensar (control de esfuerzo/razonamiento) y dedica tus palabras al resultado, no a «piensa paso a paso».",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "Empezar aclarando ahorra turnos perdidos: el modelo reúne el contexto que falta en vez de adivinar.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "Los criterios de resultado (qué significa «bueno») superan a las instrucciones de proceso en los modelos de 2026.",
  "Verification steps reduce errors on factual/analytical tasks.": "Los pasos de verificación reducen errores en tareas de datos y análisis.",
  "Explicit sections prevent rambling updates": "Las secciones explícitas evitan actualizaciones interminables",
  "Asking for risks surfaces what you forgot": "Preguntar por los riesgos saca a la luz lo que olvidaste",
  "Outcome framing keeps feedback constructive": "Describir el resultado mantiene los comentarios constructivos",
  "Explicit audience prevents vague procedures": "Indicar el público evita procedimientos vagos",
  "Spaced repetition beats massed practice": "El repaso espaciado supera a estudiar todo de golpe",
  "Worked examples aid transfer to new problems": "Los ejemplos resueltos ayudan con problemas nuevos",
  "Planning prompts reduce rework on complex tasks": "Pedir un plan reduce rehacer trabajo en tareas complejas",
  "Explicitly requesting edge cases improves coverage": "Pedir explícitamente los casos límite mejora la cobertura",
  "Specificity outperforms enthusiasm in cold outreach": "En un primer contacto, la precisión supera al entusiasmo",
  "Goal-anchored planning beats idea dumps": "Planificar con un objetivo supera a volcar ideas",
  "Requesting alternatives counters fixation": "Pedir alternativas evita aferrarse a una sola idea",
  "Citation requirements reduce unsupported claims": "Exigir citas reduce las afirmaciones sin respaldo",
  "Grounding in supplied sources reduces hallucination; tell it to admit gaps.": "Basarse en las fuentes que das reduce lo inventado; pídele que admita lo que no sabe.",
  "Searching the web for facts and figures…": "Buscando datos y cifras en la web…",
