  "Couldn't copy — press and hold the log to select it": "No se pudo copiar: mantén pulsado el registro para seleccionarlo",
  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "Estudio está dibujando con el procesador (lento). Este teléfono tiene chip gráfico: pruébalo, las imágenes y la nitidez ×4 son muchas veces más rápidas ahí.",
  "The next picture uses the graphics chip": "La próxima imagen usará el chip gráfico",
  "This picture was drawn on the CPU because the graphics chip didn't finish; the next picture tries the graphics chip again.": "Esta imagen se dibujó con la CPU porque el chip gráfico no terminó; la próxima volverá a probar el chip gráfico.",
  "Drawing on the GPU failed twice, so Attune switched Studio to the CPU. ": "Dibujar con la GPU falló dos veces, así que Attune pasó Estudio a la CPU. ",
  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "El controlador de la GPU se bloqueó dos veces al cargar el modelo de imágenes, así que Attune pasó Estudio a la CPU (puedes volver a probar la GPU abajo).",
  "Show only the models worth using on this device": "Mostrar solo los modelos que vale la pena usar en este dispositivo",
  "Combine your data": "Combina tus datos",
  "{t} › {f} holds {to} names ({m} of {n} found).": "{t} › {f} contiene nombres de {to} (se encontraron {m} de {n}).",
  "Not in {to} yet: {x}": "Aún no está en {to}: {x}",
