  "{n} added to {to}": "{n} añadidos a {to}",
  "When a column in one table names records of another (a job's customer, an invoice's crane), the phone finds it here and links them — no relationships to draw by hand.": "Cuando una columna de una tabla nombra registros de otra (el cliente de un trabajo, la grúa de una factura), el teléfono lo detecta aquí y los vincula, sin dibujar relaciones a mano.",
