  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "Desde la app de notas del teléfono: abre una nota (o selecciona varias) → Compartir → Attune → “Guardar en el Estante”. O elige aquí archivos exportados: texto, Word, PDF, páginas web, Google Keep, Evernote, un .zip o fotos de notas.",
  "Versions & prices": "Versiones y precios",
