  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "No se encontró nada: prueba a añadir el nombre de la zona (p. ej., “… New Cairo”) o mueve el mapa allí y vuelve a buscar.",
