  "Couldn't get your location — check that location is on.": "No se pudo obtener tu ubicación: comprueba que esté activada.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "“{n}” ya no está guardado en este teléfono: vuelve a elegir el archivo.",
  "tap to continue": "toca para continuar",
  "The text and your questions are kept on this phone only. Forget removes them.": "El texto y tus preguntas se guardan solo en este teléfono. Olvidar los borra.",
  "Web · Auto": "Web · Auto",
  "Web: Auto — it searches only when a question needs fresh facts": "Web: Auto — solo busca cuando una pregunta necesita datos recientes",
