  "Reading your {f} conversation…": "Leyendo tu conversación de {f}…",
  "Reading the conversation…": "Leyendo la conversación…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "Los enlaces compartidos se abren en la app de Android; o pega aquí el texto de la conversación.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "Leí tu conversación con {f}{t} (unas {n} palabras). Pregúntame lo que quieras: revisarla, resumirla o seguir desde donde se quedó.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · la IA funciona en tu dispositivo · sin cuenta ni inicio de sesión · busca en la web solo cuando una pregunta lo necesita (Auto); desactívalo con el botón Web",
  "Web: Off — nothing is looked up": "Web: desactivada — no se busca nada",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "Aunque Web esté desactivada en el Chat, las preguntas sobre precios, especificaciones, noticias, resultados o este año se siguen buscando (solo salen del teléfono las palabras de búsqueda). Desactivado: no se busca nada salvo que actives Web.",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "El modelo escribió sin sentido; reiniciándolo en modo seguro y preguntando otra vez…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "Este modelo escribe sin sentido en este teléfono, incluso en modo seguro. Elige otro modelo en Motor (Core funciona bien) y dinos cuál falló.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "El modo seguro está activo para este modelo: una vez escribió sin sentido en este teléfono, así que funciona sin trucos de velocidad y con memoria de precisión completa (un poco más lento, mismas respuestas).",
