  "Ask the airline for the reason: weather or an air-traffic strike would cancel it; a technical fault or crew shortage would not.": "Pregunta a la aerolínea el motivo: el mal tiempo o una huelga de control aéreo lo cancelarían; un fallo técnico o la falta de tripulación no.",
