  "Was the airline a UK one? (UK rules cover flights INTO the UK only on UK airlines)": "¿La aerolínea era británica? (Las normas del Reino Unido cubren los vuelos CON DESTINO al Reino Unido solo en aerolíneas británicas)",
  "Which airline was it? (Canada's amounts depend on its size)": "¿Qué aerolínea era? (Los importes de Canadá dependen de su tamaño)",
  "How late did you arrive at your destination (hours)?": "¿Con cuántas horas de retraso llegaste a tu destino?",
  "Over 3,500 km with a 3–4 hour delay: the airline may halve it.": "Más de 3.500 km con un retraso de 3–4 horas: la aerolínea puede reducirlo a la mitad.",
  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "Avisado con 7–13 días de antelación: no te deben nada si te ofrecieron un vuelo que saliera como máximo 2 h antes y llegara como máximo 4 h después que el tuyo.",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "Avisado con menos de 7 días de antelación: no te deben nada solo si te ofrecieron un vuelo que saliera como máximo 1 h antes y llegara como máximo 2 h después que el tuyo.",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "Se debe cuando el retraso estaba bajo el control de la aerolínea y no era por seguridad. Reclama en el plazo de 1 año.",
